module hw_bemsa
  implicit none
contains
  function hw_emsav(x,c) result(v)
    implicit none
    real,dimension(1:21)::x
    real,dimension(0:17539)::p
    real,dimension(0:17539)::c
    real::v
    
    call hw_bemsav(x,p)
    v = dot_product(p,c)
    
    return
  end function hw_emsav


  subroutine hw_bemsav(x,p)
    implicit none
    real,dimension(1:21)::x
    real,dimension(0:16565)::m
    real,dimension(0:17539)::p
    ! ::::::::::::::::::::

    
    call hw_evmono(x,m)
    call hw_evpoly(m,p)
    
    return
  end subroutine hw_bemsav
  
  
      subroutine hw_get_x(xyz,x,r)
!   xyz must be in Bohr
      implicit none
      integer :: i,j,k
      real :: xyz(7,3)
      real,dimension(1:21)::x
      real :: r(7,7)
      real,parameter::a=3.d0

       x( 1 ) = sqrt((xyz( 1 , 1 )-xyz( 2 , 1 ))**2+ &
             (xyz(1,2)-xyz(2,2))**2+ &
             (xyz(1,3)-xyz(2,3))**2)
       x( 2 ) = sqrt((xyz( 1 , 1 )-xyz( 3 , 1 ))**2+ &
             (xyz(1,2)-xyz(3,2))**2+ &
             (xyz(1,3)-xyz(3,3))**2)
       x( 3 ) = sqrt((xyz( 1 , 1 )-xyz( 4 , 1 ))**2+ &
             (xyz(1,2)-xyz(4,2))**2+ &
             (xyz(1,3)-xyz(4,3))**2)
       x( 4 ) = sqrt((xyz( 1 , 1 )-xyz( 5 , 1 ))**2+ &
             (xyz(1,2)-xyz(5,2))**2+ &
             (xyz(1,3)-xyz(5,3))**2)
       x( 5 ) = sqrt((xyz( 1 , 1 )-xyz( 6 , 1 ))**2+ &
             (xyz(1,2)-xyz(6,2))**2+ &
             (xyz(1,3)-xyz(6,3))**2)
       x( 6 ) = sqrt((xyz( 1 , 1 )-xyz( 7 , 1 ))**2+ &
             (xyz(1,2)-xyz(7,2))**2+ &
             (xyz(1,3)-xyz(7,3))**2)
       x( 7 ) = sqrt((xyz( 2 , 1 )-xyz( 3 , 1 ))**2+ &
             (xyz(2,2)-xyz(3,2))**2+ &
             (xyz(2,3)-xyz(3,3))**2)
       x( 8 ) = sqrt((xyz( 2 , 1 )-xyz( 4 , 1 ))**2+ &
             (xyz(2,2)-xyz(4,2))**2+ &
             (xyz(2,3)-xyz(4,3))**2)
       x( 9 ) = sqrt((xyz( 2 , 1 )-xyz( 5 , 1 ))**2+ &
             (xyz(2,2)-xyz(5,2))**2+ &
             (xyz(2,3)-xyz(5,3))**2)
       x( 10 ) = sqrt((xyz( 2 , 1 )-xyz( 6 , 1 ))**2+ &
             (xyz(2,2)-xyz(6,2))**2+ &
             (xyz(2,3)-xyz(6,3))**2)
       x( 11 ) = sqrt((xyz( 2 , 1 )-xyz( 7 , 1 ))**2+ &
             (xyz(2,2)-xyz(7,2))**2+ &
             (xyz(2,3)-xyz(7,3))**2)
       x( 12 ) = sqrt((xyz( 3 , 1 )-xyz( 4 , 1 ))**2+ &
             (xyz(3,2)-xyz(4,2))**2+ &
             (xyz(3,3)-xyz(4,3))**2)
       x( 13 ) = sqrt((xyz( 3 , 1 )-xyz( 5 , 1 ))**2+ &
             (xyz(3,2)-xyz(5,2))**2+ &
             (xyz(3,3)-xyz(5,3))**2)
       x( 14 ) = sqrt((xyz( 3 , 1 )-xyz( 6 , 1 ))**2+ &
             (xyz(3,2)-xyz(6,2))**2+ &
             (xyz(3,3)-xyz(6,3))**2)
       x( 15 ) = sqrt((xyz( 3 , 1 )-xyz( 7 , 1 ))**2+ &
             (xyz(3,2)-xyz(7,2))**2+ &
             (xyz(3,3)-xyz(7,3))**2)
       x( 16 ) = sqrt((xyz( 4 , 1 )-xyz( 5 , 1 ))**2+ &
             (xyz(4,2)-xyz(5,2))**2+ &
             (xyz(4,3)-xyz(5,3))**2)
       x( 17 ) = sqrt((xyz( 4 , 1 )-xyz( 6 , 1 ))**2+ &
             (xyz(4,2)-xyz(6,2))**2+ &
             (xyz(4,3)-xyz(6,3))**2)
       x( 18 ) = sqrt((xyz( 4 , 1 )-xyz( 7 , 1 ))**2+ &
             (xyz(4,2)-xyz(7,2))**2+ &
             (xyz(4,3)-xyz(7,3))**2)
       x( 19 ) = sqrt((xyz( 5 , 1 )-xyz( 6 , 1 ))**2+ &
             (xyz(5,2)-xyz(6,2))**2+ &
             (xyz(5,3)-xyz(6,3))**2)
       x( 20 ) = sqrt((xyz( 5 , 1 )-xyz( 7 , 1 ))**2+ &
             (xyz(5,2)-xyz(7,2))**2+ &
             (xyz(5,3)-xyz(7,3))**2)
       x( 21 ) = sqrt((xyz( 6 , 1 )-xyz( 7 , 1 ))**2+ &
             (xyz(6,2)-xyz(7,2))**2+ &
             (xyz(6,3)-xyz(7,3))**2)



     
     do i=1,7
       r(i,i)=0.d0
       do j=i+1,7
         r(i,j)=sqrt( (xyz(i,1)-xyz(j,1))**2 + (xyz(i,2)-xyz(j,2))**2 + &
			(xyz(i,3)-xyz(j,3))**2 )
         r(j,i)=r(i,j)
       enddo
      enddo

    x(1) = dexp(-x(1)/a) 
    x(2) = dexp(-x(2)/a) 
    x(3) = dexp(-x(3)/a) 
    x(4) = dexp(-x(4)/a) 
    x(5) = dexp(-x(5)/a) 
    x(6) = dexp(-x(6)/a) 
    x(7) = dexp(-x(7)/a) 
    x(8) = dexp(-x(8)/a) 
    x(9) = dexp(-x(9)/a) 
    x(10) = dexp(-x(10)/a) 
    x(11) = dexp(-x(11)/a) 
    x(12) = dexp(-x(12)/a) 
    x(13) = dexp(-x(13)/a) 
    x(14) = dexp(-x(14)/a) 
    x(15) = dexp(-x(15)/a) 
    x(16) = dexp(-x(16)/a) 
    x(17) = dexp(-x(17)/a) 
    x(18) = dexp(-x(18)/a) 
    x(19) = dexp(-x(19)/a) 
    x(20) = dexp(-x(20)/a) 
    x(21) = dexp(-x(21)/a) 

  end subroutine

