    real::c(0:17539),m(0:16565),p(0:17539)
    real::xyz(7,3),r(7,7)
    !::::::::::::::::::::
    real::pp(0:17539),mp(0:16565),xxp(1:21)
    real,parameter::a=3.0
    pp(17539)=c(17539)
